import re
S=[]
def scr(id,title,body,notes):
    n="".join(f"<li><b>{i+1}.</b> {x}</li>" for i,x in enumerate(notes))
    S.append((id,title,f'<section class="screen" id="{id}" aria-labelledby="{id}-h"><h2 id="{id}-h">{title}</h2><div class="row"><div class="frame">{body}</div><aside class="notes" aria-label="Annotations"><h3>UX notes</h3><ol>{n}</ol></aside></div></section>'))
DIS='<p class="disc">Stock tokens are not available to US persons or residents of restricted regions and are not shares. Final copy pending legal review.</p>'
nav='<div class="bar"><b>[Logo] StockClaw</b><span>How it works · Clients · Safety · FAQ</span><button>Get started</button></div>'
app=lambda a:'<div class="bar"><b>[Logo] StockClaw</b><nav aria-label="Dashboard">'+" · ".join(f"<u aria-current='page'>{x}</u>" if x==a else x for x in ["Overview","Orders","History","Fees","Agent key"])+'</nav><span><label><input type=checkbox role=switch checked> Agent active (Pause = revoke)</label> <button class="danger">Revoke</button></span></div>'
ST=["Eligibility","Wallet","Agent key","Faucet","AI client"]
steps=lambda k:'<ol class="steps" aria-label="Onboarding progress">'+"".join(f'<li class="{"on" if i==k else "done" if i<k else ""}" {"aria-current=step" if i==k else ""}>{i+1}. {x}</li>' for i,x in enumerate(ST))+'</ol>'
B=lambda t,c="":f'<div class="box {c}">{t}</div>'
REG="the US (persons and territories), Canada, the UK, Switzerland, the UAE, and sanctioned countries"
scr("L1","1. Landing page",nav+B('<h1>Let your AI agent trade tokenized stocks — inside limits you set.</h1><p>MCP connector for Claude, ChatGPT, Grok & Cursor. Robinhood Chain stock tokens + USDG.</p><button>Try the demo</button> <label>Join waitlist <input type="email" placeholder="you@example.com"></label> <button class="sec">Join</button><div class="img">[Hero illustration: chat → trade card]</div>',"hero")+
 '<h3>How it works</h3><div class="cols">'+B("① Check eligibility & connect your wallet<br>You own your wallet. We never hold its owner key. Your agent uses a limited key you can revoke anytime.")+B("② Create an agent key<br>$100/trade, $500/day, allowlist-only by default")+B("③ Add to your AI client<br>Ask your agent to trade; revoke anytime")+'</div>'+
 '<h3>Supported AI clients</h3><div class="cols">'+"".join(B(f"[icon] {c}") for c in ["Claude","ChatGPT","Grok","Cursor"])+'</div>'+
 '<h3>Safety & limits</h3><div class="cols">'+B("Onchain spend caps")+B("Ticker allowlist")+B("Key expires ≤7 days")+B("One-click revoke")+'</div>'+
 '<p><b>Fees:</b> 0.30% per trade, taken from the input token. Quotes are shown net of the fee. No subscriptions.</p><h3>FAQ</h3>'+"".join(f'<details><summary>{q}</summary><p>[Answer TBD]</p></details>' for q in ["What are stock tokens?","Who is eligible?","Do you hold my keys? — You own your wallet. We never hold its owner key. Your agent uses a limited key you can revoke anytime.","What fees apply?","How do I stop my agent?","Is this real money? (No — sample data)"])+DIS+B('<b>Ready?</b> <button>Try the demo</button>',"cta")+'<div class="foot">Footer: Terms · Privacy · Disclosures · Status</div>',
 ["Hero leads with control ('limits you set'), the main trust objection.","Waitlist in hero per ARCHITECTURE §12 AC; demo CTA primary.","No tier/subscription pricing shown; only the 0.30% fee.","FAQ uses native &lt;details&gt;. Focus order: skip-link → nav → hero CTA/waitlist → sections → FAQ → CTA → footer."])
scr("O1","2. Onboarding · Eligibility check (step 1)",steps(0)+'<h3>Check eligibility</h3><label>Country / region of residence<br><select><option>Select…</option></select></label><br><label><input type="checkbox"> I am not a US person [definition] and not a resident of '+REG+'.</label><br><p class="muted">You will sign this attestation with your wallet in the next step. Identity check: [provider placeholder].</p><button>Continue</button><div class="cols">'+B("✓ <b>Eligible</b><br>Continue to connect your wallet.","ok")+B("✕ <b>Not available in your region</b><br>Stock tokens aren't offered where you live. [Learn why] [Contact support]","err")+B("✕ <b>Blocked by network location (451)</b><br>Your connection appears to be from a restricted region.","err")+B("⏳ <b>Pending</b><br>[Provider placeholder] review. Resume via email.","status")+'</div>'+DIS,
 ["Step 1, before anything else, so blocked users learn early.","Edge geo-block (451) state mirrors ARCHITECTURE §6.","Status uses icon + text, not color alone.","Calls api.check_eligibility(); attestation signature captured in step 2 (needs a wallet)."])
scr("O2","3. Onboarding · Connect wallet & create smart wallet",steps(1)+'<h3>Connect your wallet</h3><p><b>You own your wallet. We never hold its owner key. Your agent uses a limited key you can revoke anytime.</b> Your wallet owns a non-custodial smart wallet on Robinhood Chain.</p><button class="sec">Connect wallet [RainbowKit / passkey]</button>'+B("✓ Owner: 0x9F00…0000 (sample)","ok")+'<h3>Sign eligibility attestation</h3><button class="sec">Sign (EIP-712, no gas)</button><h3>Create smart wallet</h3><button>Create smart wallet</button>'+B("✓ Smart wallet: 0xABCD…1234 (sample) [Copy] [View on explorer]","ok")+B("✕ Wrong network. Switch to Robinhood Chain. [Switch]","err")+B("✕ Couldn't create wallet. Nothing was charged. [Try again]","err"),
 ["Three sub-steps on one screen with clear checkmarks keeps 5-min-to-first-swap target.","Wrong-network error is the most likely failure; one-click switch.","api.submit_attestation, api.create_smart_account."])
scr("O3","4. Onboarding · Create agent key (limits)",steps(2)+'<h3>Create your agent key</h3><p>A scoped key your AI agent uses. It can only trade through StockClaw, within these limits, and it expires.</p><div class="cols">'+B('<label>Max per trade (USDG)<br><input value="100"></label>')+B('<label>Daily cap (USDG)<br><input value="500"></label>')+B('<label>Expires in<br><select><option>7 days (max)</option><option>1 day</option></select></label>')+'</div>'+B('<b>Allowlisted tickers</b> (allowlist-only, always on)<br>[TSLA ✕] [AMZN ✕] [PLTR ✕] [NFLX ✕] [AMD ✕] <label>Add <input placeholder="Search"></label>')+'<p class="muted">Over-limit trades are blocked onchain. No one-off approvals.</p><button>Create agent key (signs 1 tx)</button>'+B("Validation: per-trade max can't exceed daily cap.","err"),
 ["Defaults pre-filled: $100 / $500 / allowlist-only / 7 days.","Allowlist is not optional — no 'any token' switch.","api.create_session_key(caps)."])
scr("O4","5. Onboarding · Get tokens (faucet)",steps(3)+'<h3>Fund your wallet</h3><p>Demo tokens have no value. This replaces deposit/bridge/card for the demo.</p><div class="cols">'+B("<b>1. ETH + stock tokens</b><br>Robinhood Chain faucet: ETH + TSLA/AMZN/PLTR/NFLX/AMD<br>[Open faucet ↗] Send to: 0xABCD…1234 [Copy]")+B("<b>2. USDG</b><br>[Claim 1,000 USDG]")+'</div>'+B('<span aria-live="polite">⏳ Waiting for balances…</span>',"status")+B("✓ Received ETH and USDG. Ready.","ok")+B("✕ Faucet rate limit reached. Try again in [time] or use [alternate faucet].","err")+'<button>Continue</button>',
 ["Faucet link opens new tab; we poll balances via api.get_balances.","USDG here is our MockUSDG; show it as USDG.","api.faucet_testnet."])
scr("O5","6. Onboarding · Connect your AI client (last step)",steps(4)+'<h3>Add StockClaw to your AI client</h3><div class="cols" role="radiogroup" aria-label="AI client">'+"".join(B(f'<label><input type="radio" name="c" {"checked" if c=="Claude" else ""}> [icon] {c}</label>') for c in ["Claude","ChatGPT","Grok","Cursor"])+'</div><ol><li>Open Claude → Settings → Connectors → Add custom connector</li><li>Paste:<pre>https://mcp.stockclaw.example/mcp   [Copy]</pre>Cursor config:<pre>{ "mcpServers": { "stockclaw": { "url": "https://mcp.stockclaw.example/mcp" } } }   [Copy]</pre></li><li>Sign in (OAuth) and approve scopes: read, trade (within agent key limits)</li></ol>'+B('<span aria-live="polite">⏳ Waiting for connection…</span>',"status")+B("✓ Connected. Try: “Quote 10 USDG of TSLA” [Copy prompt]","ok")+B("✕ Authorization denied or timed out. [Retry] [Troubleshoot]","err")+'<button>Go to dashboard</button>',
 ["Last step so the first agent prompt can succeed immediately (funded, keyed).","Instructions swap per selected client. Copy buttons announce via aria-live.","Write tools prompt for confirmation in the client (destructiveHint)."])
scr("D1","7. Dashboard · Overview (balances & prices)",app("Overview")+'<div class="cols">'+B("Agent key<br><b>● Active</b>, expires Oct 25 (sample)<br>Today: $42 / $500<div class='meter'><i style='width:8%'></i></div>")+B("Per-trade cap<br><b>$100</b><br><u>Edit limits</u>")+'</div><h3>Balances</h3><table data-api="get_balances"><caption class="sr">Balances</caption><thead><tr><th>Token</th><th>Amount</th><th>Value (sample)</th></tr></thead><tbody></tbody></table><h3>Prices (MockAggregatorV3)</h3><table data-api="list_assets"><thead><tr><th>Token</th><th>Price (sample)</th><th>Source</th></tr></thead><tbody></tbody></table>'+B("Empty: No balances yet. [Get tokens]","empty"),
 ["Tables render from api.js (data-api attribute) so wiring = replacing stubs.","Revoke is in the top bar on every page.","Data must reflect onchain state within 30s (poll / refresh indicator TBD)."])
scr("D2","8. Dashboard · Open orders (DCA & limits)",app("Orders")+'<p></p><table data-api="list_orders"><thead><tr><th>Type</th><th>Pair</th><th>Amount</th><th>Schedule / limit</th><th>Status</th><th>Action</th></tr></thead><tbody></tbody></table>'+B("Empty: No open orders. Ask your agent: “DCA 10 USDG into TSLA daily”.","empty")+B("Error: Couldn't load orders. [Retry]","err"),
 ["Cancel per row calls api.cancel_order (onchain tx; show pending → confirmed).","Orders created by the agent; UI is read + cancel only."])
scr("D3","9. Dashboard · Trade history",app("History")+'<p></p><table data-api="get_history"><thead><tr><th>Time</th><th>In</th><th>Out</th><th>Fee (0.30%, from input)</th><th>Status</th><th>Explorer</th></tr></thead><tbody></tbody></table>'+B("Empty: No trades yet.","empty"),
 ["Blocked trades show the rule and link to <u>Agent key → limits</u>; hard block, no approvals.","Each filled row links to Blockscout.","Amounts net of fee: in = gross, fee shown separately."])
scr("D4","10. Dashboard · Fees",app("Fees")+'<div class="cols">'+B("Fee rate<br><b>0.30%</b><br>taken from input token")+B("Fees paid (sample)<br><b>0.03 USDG</b>")+'</div>'+B("Example (sample): 10.00 USDG in → 0.03 fee → 9.97 swapped. Quotes are shown net of fee.")+'<p class="muted">Network gas is paid in ETH.</p>'+B("Empty: No fees yet.","empty"),
 ["No tiers or subscriptions.","Fee math comes from api.quote_swap (feeAmount)."])
scr("D5","11. Dashboard · Agent key: limits & revoke",app("Agent key")+'<div class="cols">'+B('<label>Max per trade (USDG)<br><input value="100"></label>')+B('<label>Daily cap (USDG)<br><input value="500"></label>')+B('Expires<br><b>Oct 25 (sample)</b> [Renew]')+'</div>'+B("Allowlist (always on): [TSLA ✕] [AMZN ✕] [PLTR ✕] [NFLX ✕] [AMD ✕] [+ Add]")+'<button>Save limits (re-issues key, 1 tx)</button>'+B('<b>Saving limits</b><ol aria-live="polite"><li>✓ Old key revoked</li><li>⏳ New key issued with $100 / $500 / allowlist, expires in 7 days</li><li>○ Agent reconnects automatically</li></ol>Error: Tx failed. Old key is still active, nothing changed. [Retry]',"status")+''+B('<b>Pause agent</b> <label><input type=checkbox role=switch checked> Active</label> Pausing revokes the key (confirmation required). Resume issues a new key with the same limits.<br><br><b>Revoke agent key</b><br>Your AI agent immediately loses the ability to trade. Open DCA/limit orders stop executing. Funds stay in your smart wallet. <button class="danger">Revoke…</button>')+B('<div role="dialog" aria-modal="true" aria-labelledby="rv"><b id="rv">Revoke agent key?</b><br>This signs one transaction. You can create a new key later.<br><button class="danger">Yes, revoke</button> <button class="sec">Cancel</button></div>',"warn")+B("✓ Revoked. Tx 0xMOCKREVOKE [explorer]. [Create new key]","ok"),
 ["One-click revoke + confirmation dialog (focus trapped, Esc cancels, focus starts on Cancel).","Pause toggle = revoke under the hood (same confirmation); resume = re-issue. Key also auto-expires after 7 days.","Saving limits re-issues the key in one tx: stepper shows old revoked → new issued; failure leaves old key intact."])
scr("D6","12. Dashboard · Global states",app("Overview")+'<div class="cols">'+B("<b>Not funded</b><br>[Get tokens]","empty")+B("<b>Agent key revoked/expired</b><br>[Create new key]","warn")+B("<b>AI client not connected</b><br>[Connect]","status")+B("<b>Service issue</b><br>Trading paused. Funds stay in your wallet. [Status]","err")+'</div>',
 ["One recovery action per banner; role=status, role=alert for errors."])
for i,(a,b,c) in enumerate(S): pass
toc="".join(f'<li><a href="#{i}">{t}</a></li>' for i,t,_ in S)
css=open("style.css").read()
render="""
const fmt={get_balances:r=>`<td>${r.symbol}</td><td>${r.amount}</td><td>$${r.usdValue.toFixed(2)}</td>`,
list_assets:r=>`<td>${r.symbol}</td><td>$00.00</td><td>${r.source}</td>`,
list_orders:r=>`<td>${r.type}</td><td>${r.tokenIn}→${r.tokenOut}</td><td>${r.amount} ${r.tokenIn}</td><td>${r.interval?r.interval+' · '+r.execs:'limit $00.00 · exp '+r.expiry.slice(0,10)}</td><td>${r.status}</td><td><button class="sec">Cancel</button></td>`,
get_history:r=>`<td>${r.ts.slice(0,16).replace('T',' ')}</td><td>${r.in}</td><td>${r.out}</td><td>${r.fee}</td><td>${r.status=='blocked'?'✕ Blocked: '+r.reason+' · <a href="#D5">Edit spending limits →</a>':'✓ Filled'}</td><td>${r.txHash?'<a href="'+EXPLORER+'/tx/'+r.txHash+'">view</a>':'—'}</td>`};
document.querySelectorAll('[data-api]').forEach(async t=>{const k=t.dataset.api;const rows=await api[k]();t.querySelector('tbody').innerHTML=rows.map(r=>'<tr>'+fmt[k](r)+'</tr>').join('')});
var h=location.hash.slice(1);if(h.startsWith('solo-')){document.body.classList.add('solo');document.getElementById(h.slice(5)).classList.add('show')}"""
open("wireframes.html","w").write(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><title>StockClaw wireframes v0.4</title><style>{css}</style></head><body><a class="sr" href="#L1">Skip to screens</a><header><h1>StockClaw wireframes v0.4 (low-fi)</h1><p>Mock data comes from api.js (inlined below; source file /workspace/stockclaw/api.js). Status never relies on color alone. Text ≥ #444 on white. Focus order: skip link → top bar → content top-to-bottom; annotations are outside the tab order.</p><ol>{toc}</ol></header>{"".join(s for _,_,s in S)}{DIS}<script>{open("api.js").read()}</script><script>{render}</script></body></html>')
open("ids","w").write(" ".join(i for i,_,_ in S))
